assets/theme.css:
/* Marble — EcomStrait Liquid theme. Symmetric and centred, wide-tracked
   headings, stone surfaces. Buttons use --brand-deep so a pale brand colour
   still meets contrast. */
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;font-family:var(--font-body);color:var(--ink);background:var(--bg);line-height:1.65;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block;object-fit:cover}
a{color:inherit;text-decoration:none}
h1,h2,h3{font-family:var(--font-heading);line-height:1.25;margin:0;font-weight:400;letter-spacing:.06em}
.muted{color:var(--muted)}
.container{width:100%;max-width:1160px;margin:0 auto;padding:0 24px}
.section{padding:88px 0}
.section--narrow{max-width:700px;margin:0 auto;text-align:center}
.section-title{font-size:clamp(1.4rem,2.6vw,1.9rem);text-transform:uppercase;letter-spacing:.18em;text-align:center}
.section-head{margin-bottom:44px}
.section-foot{margin-top:48px;text-align:center}

/* The centred hairline that punctuates every heading */
.rule-center{display:block;width:64px;height:1px;background:var(--brand-deep);margin:20px auto 0;position:relative}
.rule-center::after{content:"";position:absolute;left:50%;top:-2px;width:5px;height:5px;background:var(--brand-deep);transform:translateX(-50%) rotate(45deg)}
.section-head .rule-center{margin-bottom:0}
.link-more{font-size:.72rem;text-transform:uppercase;letter-spacing:.2em;color:var(--muted);border-bottom:1px solid var(--line);padding-bottom:5px;transition:color .25s ease,border-color .25s ease}
.link-more:hover{color:var(--ink);border-color:var(--brand-deep)}

/* Buttons — deepened brand so pale palettes stay readable */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;border:1px solid var(--brand-deep);cursor:pointer;font-family:var(--font-body);font-weight:600;font-size:.74rem;text-transform:uppercase;letter-spacing:.2em;padding:.9rem 1.9rem;border-radius:var(--radius);transition:background-color .3s ease,color .3s ease}
.btn-lg{padding:1.05rem 2.6rem;font-size:.78rem}
.btn-primary{background:var(--brand-deep);color:var(--bg)}
.btn-primary:hover{background:transparent;color:var(--brand-deep)}
.btn-primary[disabled]{background:transparent;color:var(--muted);border-color:var(--line);cursor:not-allowed}
.btn-ghost{background:transparent;border-color:var(--line);color:var(--muted)}
.btn-ghost:hover{border-color:var(--brand-deep);color:var(--ink)}

/* Header — centred nav under a stone rule */
.site-header{position:sticky;top:0;z-index:20;background:color-mix(in srgb,var(--bg) 92%,transparent);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.site-header__inner{display:flex;align-items:center;justify-content:space-between;gap:28px;height:84px}
.site-header__name{font-family:var(--font-heading);font-size:1.25rem;text-transform:uppercase;letter-spacing:.24em}
.site-nav{display:flex;gap:30px}
.site-nav__link{font-size:.72rem;text-transform:uppercase;letter-spacing:.18em;color:var(--muted);padding-bottom:3px;border-bottom:1px solid transparent;transition:color .25s ease,border-color .25s ease}
.site-nav__link:hover,.site-nav__link.is-active{color:var(--ink);border-color:var(--brand-deep)}
.site-header__cart{font-size:.72rem;text-transform:uppercase;letter-spacing:.18em;display:inline-flex;align-items:center;gap:9px}
.cart-count{display:inline-grid;place-items:center;min-width:21px;height:21px;padding:0 6px;border-radius:999px;background:var(--brand-deep);color:var(--bg);font-size:.7rem;letter-spacing:0}
@media (max-width:640px){.site-nav{display:none}.site-header__inner{height:66px}}

/* Hero — centred, stone gradient */
.hero{background:linear-gradient(165deg,var(--stone-2) 0%,var(--stone) 46%,var(--bg) 100%);background-size:cover;background-position:center;border-bottom:1px solid var(--line)}
.hero__inner{padding:128px 24px;text-align:center;max-width:760px;margin:0 auto}
.hero__heading{font-size:clamp(1.9rem,4.6vw,3.1rem);text-transform:uppercase;letter-spacing:.14em}
.hero__subheading{font-size:clamp(.98rem,1.6vw,1.12rem);color:var(--muted);margin:26px auto 36px;max-width:46ch}
.hero--image .hero__inner{padding:168px 24px}
@media (max-width:640px){.hero__inner,.hero--image .hero__inner{padding:80px 24px}}

/* Grids */
.grid{display:grid;gap:32px 26px}
.grid-products{grid-template-columns:repeat(2,1fr)}
.grid-collections{grid-template-columns:repeat(2,1fr)}
.grid-3{grid-template-columns:repeat(3,1fr);gap:0}
@media (min-width:720px){.grid-products{grid-template-columns:repeat(4,1fr)}.grid-collections{grid-template-columns:repeat(3,1fr)}}
@media (max-width:640px){.grid-3{grid-template-columns:1fr}}

/* Product card — centred captions on stone */
.product-card{display:flex;flex-direction:column;overflow:hidden;background:transparent;text-align:center}
.product-card__media{position:relative;aspect-ratio:1/1;overflow:hidden;background:var(--stone)}
.product-card__media img{width:100%;height:100%;transition:transform .7s cubic-bezier(.22,.61,.36,1)}
.product-card:hover .product-card__media img{transform:scale(1.04)}
.product-card__placeholder,.product-card--placeholder{aspect-ratio:1/1;background:linear-gradient(165deg,var(--stone-2),var(--stone))}
.product-card__body{padding:18px 6px 0;display:flex;flex-direction:column;gap:7px}
.product-card__title{font-family:var(--font-heading);font-size:.86rem;text-transform:uppercase;letter-spacing:.12em;line-height:1.5}
.product-card__price{font-size:.86rem;color:var(--muted)}
.badge{position:absolute;top:14px;left:50%;transform:translateX(-50%);padding:5px 14px;border-radius:var(--radius);font-size:.62rem;text-transform:uppercase;letter-spacing:.18em;background:var(--bg);color:var(--ink);border:1px solid var(--line)}
.price--sale .price__was{color:var(--muted);margin-right:8px}
.price--sale .price__now{color:var(--ink)}

/* Product page */
.product{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:start}
@media (max-width:820px){.product{grid-template-columns:1fr;gap:36px}}
.product__info{text-align:center}
.product__title{font-size:clamp(1.5rem,2.8vw,2.1rem);text-transform:uppercase;letter-spacing:.14em}
.product__price{font-size:1.1rem;color:var(--muted);margin:22px 0 32px;padding-bottom:30px;border-bottom:1px solid var(--line)}
.product__options{display:flex;flex-wrap:wrap;gap:20px;margin-bottom:28px;justify-content:center}
.product__option{display:flex;flex-direction:column;gap:9px;font-size:.66rem;text-transform:uppercase;letter-spacing:.2em;color:var(--muted)}
.product__option select{padding:.7rem 1rem;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);color:var(--ink);font-family:var(--font-body);font-size:.9rem;letter-spacing:0;text-transform:none}
.product__option select:focus-visible{outline:1px solid var(--brand-deep);outline-offset:1px}
.product__description{margin-top:40px;padding-top:30px;border-top:1px solid var(--line);text-align:left;color:var(--muted)}
.product__media-placeholder{aspect-ratio:1/1;background:linear-gradient(165deg,var(--stone-2),var(--stone))}

/* Value props — centred, divided by hairlines */
.value-props{background:var(--stone)}
.value-prop{padding:8px 32px;text-align:center;border-left:1px solid var(--line)}
.value-prop:first-child{border-left:0}
.value-prop__title{font-size:.78rem;text-transform:uppercase;letter-spacing:.2em;margin-bottom:12px}
@media (max-width:640px){.value-prop{border-left:0;border-top:1px solid var(--line);padding:26px 0}.value-prop:first-child{border-top:0}}

/* Cart */
.cart-line{display:grid;grid-template-columns:80px 1fr auto auto;gap:22px;align-items:center;padding:22px 0;border-bottom:1px solid var(--line)}
.cart-line__title{font-family:var(--font-heading);font-size:.86rem;text-transform:uppercase;letter-spacing:.12em}
.cart-line__qty{width:66px;padding:.55rem;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);text-align:center;color:var(--ink);font-family:var(--font-body)}
.cart-footer{display:flex;flex-wrap:wrap;justify-content:space-between;gap:20px;align-items:center;padding-top:28px}
.cart-subtotal{display:flex;align-items:baseline;gap:14px;font-size:.7rem;text-transform:uppercase;letter-spacing:.2em;color:var(--muted)}
.cart-subtotal strong{font-family:var(--font-heading);font-size:1.45rem;font-weight:400;letter-spacing:.04em;color:var(--ink)}
.cart-actions{display:flex;gap:14px}

/* Collections */
.collection-card{position:relative;display:block;overflow:hidden;background:var(--stone)}
.collection-card img{transition:transform .7s cubic-bezier(.22,.61,.36,1)}
.collection-card:hover img{transform:scale(1.04)}
.collection-card__title{position:absolute;left:50%;bottom:18px;transform:translateX(-50%);background:var(--bg);padding:9px 20px;border-radius:var(--radius);font-family:var(--font-heading);font-size:.74rem;text-transform:uppercase;letter-spacing:.16em;white-space:nowrap}
.collection-head{margin-bottom:44px;text-align:center}
.collection-head__desc{max-width:54ch;margin:20px auto 0;text-align:center}

/* Misc */
.rte{max-width:60ch;margin:0 auto}
.rte a{color:var(--ink);text-decoration:underline;text-decoration-color:var(--brand-deep);text-underline-offset:4px}
.pagination{display:flex;gap:22px;justify-content:center;margin-top:52px;font-size:.78rem;letter-spacing:.12em;color:var(--muted)}
.pagination a:hover{color:var(--ink)}
.pagination .is-current{color:var(--ink);border-bottom:1px solid var(--brand-deep)}
.search-form{display:flex;gap:12px;margin:28px auto 40px;max-width:520px}
.search-form input{flex:1;padding:.85rem 1.1rem;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);color:var(--ink);font-family:var(--font-body)}
.search-form input::placeholder{color:var(--muted)}
.search-form input:focus-visible{outline:1px solid var(--brand-deep);outline-offset:1px}
:focus-visible{outline:1px solid var(--brand-deep);outline-offset:2px}

/* Footer */
.site-footer{margin-top:72px;border-top:1px solid var(--line);padding:60px 0 30px;background:var(--stone)}
.site-footer__inner{display:flex;flex-wrap:wrap;justify-content:space-between;gap:34px}
.site-footer__name{font-family:var(--font-heading);font-size:1.05rem;text-transform:uppercase;letter-spacing:.22em;margin:0 0 10px}
.site-footer__nav{display:flex;flex-direction:column;gap:12px;font-size:.74rem;text-transform:uppercase;letter-spacing:.14em;color:var(--muted)}
.site-footer__nav a:hover{color:var(--ink)}
.site-footer__legal{margin-top:44px;padding-top:24px;border-top:1px solid var(--line);font-size:.7rem;letter-spacing:.12em;text-align:center}

@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}

